/**
 * `nexus worktree <subcommand>`: one argument parser and dispatcher shared by the CLI command, the `/worktree` slash
 * command (REPL and sidecar) and the tests. Mutating subcommands are refused in read-only mode here as well as at the
 * two slash gates, so no entry point can reach them.
 */
import { redactSecrets } from "../ui.js";
import { homeDir, listWorktrees, pathOf, removeWorktrees, switchWorktree, WorktreeError, type CommandResult, type WorktreeContext } from "./core.js";
import { copyIgnored } from "./copy.js";
import { generateMergeMessage, DEFAULT_AI_TIMEOUT_MS, type Completer } from "./ai_message.js";
import { mergeWorktree, parseAge, pruneWorktrees } from "./merge.js";
import { GitError } from "./git.js";
import { WorktreePathError } from "./paths.js";

export interface RunContext {
  cwd: string;
  home?: string;
  readOnly?: boolean;
}

interface Parsed { positionals: string[]; flags: Set<string>; values: Map<string, string> }

interface Spec { booleans: Record<string, string>; values: Record<string, string>; positional: string }

const SPECS: Record<string, Spec> = {
  switch: { booleans: { "-c": "create", "--create": "create", "--no-copy": "no-copy" }, values: { "--base": "base" }, positional: "<branch>" },
  "copy-ignored": { booleans: { "--force": "force", "-f": "force", "--dry-run": "dry-run", "--all-ignored": "all-ignored" }, values: { "--from": "from", "--to": "to" }, positional: "" },
  list: { booleans: { "--json": "json" }, values: { "--limit": "limit" }, positional: "" },
  remove: { booleans: { "--force": "force", "-f": "force", "--delete-unmerged": "delete-unmerged" }, values: {}, positional: "<branch|path>..." },
  path: { booleans: {}, values: {}, positional: "<branch|path>" },
  merge: { booleans: { "--no-squash": "no-squash", "--no-rebase": "no-rebase", "--no-remove": "no-remove", "--no-verify-receipt": "no-verify-receipt", "--ai-message": "ai-message" }, values: { "--message": "message", "-m": "message", "--reason": "reason" }, positional: "[target]" },
  prune: { booleans: { "--dry-run": "dry-run", "--discard-ignored": "discard-ignored" }, values: { "--min-age": "min-age", "--limit": "limit" }, positional: "" },
};

const ALIASES: Record<string, string> = { copy: "copy-ignored", ls: "list", status: "list", rm: "remove", sw: "switch" };

/** Subcommands that only read. Used by the slash gates and by `runWorktreeCommand`. */
const READ_ONLY = new Set(["list", "path"]);
/** Subcommands that mutate unless `--dry-run` is given. */
const READ_ONLY_WITH_DRY_RUN = new Set(["copy-ignored", "prune"]);

export const WORKTREE_USAGE = "worktree [list|path <branch>|switch [-c] <branch> [--base B] [--no-copy]|remove <branch>... [--force] [--delete-unmerged]|copy-ignored [--from B] [--to B] [--force] [--dry-run] [--all-ignored]|merge [target] [--no-squash] [--no-rebase] [--no-remove] [--no-verify-receipt --reason why] [--ai-message]|prune [--dry-run] [--min-age 1d] [--limit N]]";

function canonical(sub: string): string | undefined {
  const name = ALIASES[sub] ?? sub;
  return SPECS[name] ? name : undefined;
}

/** True when `args` (the text after `/worktree` or `nexus worktree`) only inspects. Empty means list. */
export function isReadOnlyWorktreeArgs(args: string): boolean {
  const sub = args.trim().split(/\s+/)[0] ?? "";
  if (!sub) return true;
  const name = canonical(sub);
  if (name === undefined) return false;
  if (READ_ONLY.has(name)) return true;
  return READ_ONLY_WITH_DRY_RUN.has(name) && args.trim().split(/\s+/).includes("--dry-run");
}

function parse(spec: Spec, tokens: string[]): Parsed {
  const parsed: Parsed = { positionals: [], flags: new Set(), values: new Map() };
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token === "--") { parsed.positionals.push(...tokens.slice(i + 1)); break; }
    if (token.length > 1 && token.startsWith("-")) {
      if (spec.booleans[token]) parsed.flags.add(spec.booleans[token]);
      else if (spec.values[token]) {
        const value = tokens[++i];
        if (value === undefined) throw new WorktreeError(`${token} needs a value`);
        parsed.values.set(spec.values[token], value);
      } else throw new WorktreeError(`unknown option ${redactSecrets(token).slice(0, 40)}`);
      continue;
    }
    parsed.positionals.push(token);
  }
  return parsed;
}

/** Runs one worktree command. Never throws: failures come back as `success: false` with a redacted message. */
export function runWorktreeCommand(tokens: string[], run: RunContext): CommandResult {
  const ctx: WorktreeContext = { cwd: run.cwd, home: run.home ?? homeDir(), readOnly: Boolean(run.readOnly) };
  try {
    const first = tokens[0] && !tokens[0].startsWith("-") ? tokens[0] : "list";
    const rest = first === tokens[0] ? tokens.slice(1) : tokens;
    const name = canonical(first);
    if (!name) throw new WorktreeError(`unknown subcommand '${redactSecrets(first).slice(0, 40)}'. Usage: ${WORKTREE_USAGE}`);
    const parsed = parse(SPECS[name], rest);
    if (ctx.readOnly && !READ_ONLY.has(name) && !(READ_ONLY_WITH_DRY_RUN.has(name) && parsed.flags.has("dry-run"))) {
      throw new WorktreeError(`read-only mode: 'worktree ${name}' changes the repository and is refused`);
    }
    switch (name) {
      case "switch": {
        if (parsed.positionals.length !== 1) throw new WorktreeError("usage: worktree switch [-c] <branch> [--base B]");
        const switched = switchWorktree(ctx, parsed.positionals[0], { create: parsed.flags.has("create"), base: parsed.values.get("base") });
        const made = switched.data as { created?: boolean; path?: string } | undefined;
        if (switched.success && made?.created && !parsed.flags.has("no-copy") && made.path) {
          // Sharing build caches is a convenience: a failure here never undoes or fails the switch.
          try {
            const copied = copyIgnored(ctx, { to: made.path });
            const data = copied.data as { copied?: number } | undefined;
            if (data?.copied) switched.output += `\n${copied.output}`;
          } catch (err) {
            switched.output += `\nwarning: copying ignored files failed: ${redactSecrets((err as Error).message).slice(0, 200)}`;
          }
        }
        return switched;
      }
      case "copy-ignored": {
        if (parsed.positionals.length) throw new WorktreeError("usage: worktree copy-ignored [--from B] [--to B] [--force] [--dry-run] [--all-ignored]");
        return copyIgnored(ctx, {
          from: parsed.values.get("from"), to: parsed.values.get("to"), force: parsed.flags.has("force"),
          dryRun: parsed.flags.has("dry-run"), allIgnored: parsed.flags.has("all-ignored"),
        });
      }
      case "list": {
        if (parsed.positionals.length) throw new WorktreeError("usage: worktree list [--json] [--limit N]");
        const limit = parsed.values.get("limit");
        if (limit !== undefined && !/^[1-9]\d{0,5}$/.test(limit)) throw new WorktreeError("--limit must be a positive integer");
        return listWorktrees(ctx, { json: parsed.flags.has("json"), limit: limit ? Number(limit) : undefined });
      }
      case "path": {
        if (parsed.positionals.length !== 1) throw new WorktreeError("usage: worktree path <branch|path>");
        return pathOf(ctx, parsed.positionals[0]);
      }
      case "merge": {
        if (parsed.positionals.length > 1) throw new WorktreeError("usage: worktree merge [target] [--no-squash] [--no-rebase] [--no-remove] [-m message]");
        return mergeWorktree(ctx, {
          target: parsed.positionals[0], noSquash: parsed.flags.has("no-squash"), noRebase: parsed.flags.has("no-rebase"),
          noRemove: parsed.flags.has("no-remove"), message: parsed.values.get("message"),
          noVerifyReceipt: parsed.flags.has("no-verify-receipt"), reason: parsed.values.get("reason"),
        });
      }
      case "prune": {
        if (parsed.positionals.length) throw new WorktreeError("usage: worktree prune [--dry-run] [--min-age 1d] [--limit N] [--discard-ignored]");
        const limit = parsed.values.get("limit");
        if (limit !== undefined && !/^[1-9]\d{0,5}$/.test(limit)) throw new WorktreeError("--limit must be a positive integer");
        const age = parsed.values.get("min-age");
        return pruneWorktrees(ctx, {
          dryRun: parsed.flags.has("dry-run"), discardIgnored: parsed.flags.has("discard-ignored"),
          minAgeMs: age === undefined ? undefined : parseAge(age), limit: limit ? Number(limit) : undefined,
        });
      }
      case "remove":
        return removeWorktrees(ctx, parsed.positionals, { force: parsed.flags.has("force"), deleteUnmerged: parsed.flags.has("delete-unmerged") });
    }
    throw new WorktreeError("unreachable");
  } catch (err) {
    if (err instanceof WorktreeError || err instanceof WorktreePathError || err instanceof GitError) return { success: false, output: redactSecrets(err.message) };
    return { success: false, output: redactSecrets((err as Error)?.message ?? String(err)).slice(0, 400) };
  }
}

/** Split the text after the command name into tokens (no quoting: branch names and paths here contain no spaces). */
export function tokenizeWorktreeArgs(args: string): string[] {
  return args.trim().split(/\s+/).filter(Boolean);
}

export interface AsyncDeps {
  /** Asks the configured model; absent when no provider is available. */
  completer?: Completer;
  aiTimeoutMs?: number;
}

/** Like `runWorktreeCommand`, plus the opt-in `merge --ai-message`. Read-only mode never reaches the model. */
export async function runWorktreeCommandAsync(tokens: string[], run: RunContext, deps: AsyncDeps = {}): Promise<CommandResult> {
  const name = tokens[0] ? canonical(tokens[0]) : undefined;
  if (name !== "merge" || run.readOnly || !tokens.includes("--ai-message")) return runWorktreeCommand(tokens, run);
  let parsed: Parsed;
  try { parsed = parse(SPECS.merge, tokens.slice(1)); } catch { return runWorktreeCommand(tokens, run); }
  if (parsed.values.has("message")) return runWorktreeCommand(tokens, run); // an explicit message wins
  const ctx: WorktreeContext = { cwd: run.cwd, home: run.home ?? homeDir(), readOnly: false };
  const generated = await generateMergeMessage(ctx, parsed.positionals[0], deps.completer, deps.aiTimeoutMs ?? DEFAULT_AI_TIMEOUT_MS)
    .catch(() => ({ message: undefined, note: "note: could not prepare the model request; using the deterministic commit message." }));
  const result = runWorktreeCommand(generated.message ? [...tokens, "-m", generated.message] : tokens, run);
  return { ...result, output: `${generated.note}\n${result.output}` };
}
/**
 * Operator-owned worktree settings: the `worktree` object in `~/.config/nexus/config.json` (version 1).
 *
 * Only the operator's own file is read. A project file (`.nexus/config.json`, a checked-in file) can never opt the
 * repository into a different layout or allow paths outside the sandbox. An invalid value is an error, never guessed.
 */
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import type { WorktreeLayout } from "./paths.js";

const LIMIT = 64 * 1024;

export interface WorktreeSettings {
  layout: WorktreeLayout;
  pathTemplate?: string;
  allowOutside: boolean;
}

export function operatorConfigPath(home: string): string {
  return path.join(home, ".config", "nexus", "config.json");
}

export function readWorktreeSettings(home: string = process.env.HOME || os.homedir()): WorktreeSettings {
  const settings: WorktreeSettings = { layout: "nexus", allowOutside: false };
  const file = operatorConfigPath(home);
  let stat: fs.Stats;
  try {
    stat = fs.lstatSync(file);
  } catch (err: any) {
    if (err?.code === "ENOENT" || err?.code === "ENOTDIR") return settings;
    throw new Error("Unable to inspect the operator config.json file.");
  }
  if (stat.isSymbolicLink() || !stat.isFile()) throw new Error("Nexus config.json must be a regular file, not a link.");
  if (stat.size > LIMIT) throw new Error("Nexus config.json exceeds the 64 KiB size limit.");
  let parsed: unknown;
  try {
    const fd = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0));
    try {
      parsed = JSON.parse(fs.readFileSync(fd, "utf8"));
    } finally {
      fs.closeSync(fd);
    }
  } catch {
    throw new Error("Nexus config.json is not valid JSON.");
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("Nexus config.json must contain a JSON object.");
  const root = parsed as Record<string, unknown>;
  if (root.version !== 1) throw new Error("Nexus config.json requires version: 1.");
  const raw = root.worktree;
  if (raw === undefined) return settings;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error("Nexus config.json worktree must be an object.");
  const block = raw as Record<string, unknown>;
  for (const key of Object.keys(block)) {
    if (!["layout", "pathTemplate", "allowOutside"].includes(key)) throw new Error(`Unsupported Nexus config.json worktree field '${key}'.`);
  }
  if (block.layout !== undefined) {
    if (block.layout !== "nexus" && block.layout !== "sibling") throw new Error("Nexus config.json worktree.layout must be \"nexus\" or \"sibling\".");
    settings.layout = block.layout;
  }
  if (block.pathTemplate !== undefined) {
    if (typeof block.pathTemplate !== "string" || !block.pathTemplate || block.pathTemplate.length > 500) throw new Error("Nexus config.json worktree.pathTemplate must be a non-empty string of at most 500 characters.");
    settings.pathTemplate = block.pathTemplate;
  }
  if (block.allowOutside !== undefined) {
    if (typeof block.allowOutside !== "boolean") throw new Error("Nexus config.json worktree.allowOutside must be true or false.");
    settings.allowOutside = block.allowOutside;
  }
  return settings;
}
/**
 * `nexus worktree merge` and `prune` (WP-1312).
 *
 * merge: commit what is dirty, squash, rebase onto the target, fast-forward only, then remove the worktree and its
 * branch. Nothing here runs a hook or an external command (commit messages are deterministic unless `--message` is
 * given). The pre-merge hook (WP-1313) will attach at `preMerge` below.
 */
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { generateConventionalCommit } from "../git.js";
import { redactSecrets } from "../ui.js";
import { removeOne, resolveBranchName, shownBranch, shownPath, statusOf, integratedReason, WorktreeError, type CommandResult, type WorktreeContext } from "./core.js";
import { git, gitOut } from "./git.js";
import { currentEntry, defaultBranch, openRepo, resolveCommit, type WorktreeEntry } from "./repo.js";
import { readRegistry, updateRegistry, MAX_RECORDS } from "./registry.js";
import { hasVerification, workingState } from "./verification.js";

export interface MergeOptions {
  target?: string;
  noSquash?: boolean;
  noRebase?: boolean;
  noRemove?: boolean;
  message?: string;
  /** Merge without a recorded verification; requires `reason`, which is recorded. */
  noVerifyReceipt?: boolean;
  reason?: string;
}

const NON_INTERACTIVE = { GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" };

function inProgress(gitDir: string): string | undefined {
  for (const name of ["rebase-merge", "rebase-apply", "MERGE_HEAD", "CHERRY_PICK_HEAD"]) {
    if (fs.existsSync(path.join(gitDir, name))) return name;
  }
  return undefined;
}

/** A commit holding the worktree exactly as `git add -A` would see it, stored under refs/nexus-backup/<branch>. */
function backup(dir: string, branch: string, dirty: boolean): string {
  let sha = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
  if (dirty) {
    const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-backup-"));
    try {
      const env = { GIT_INDEX_FILE: path.join(scratch, "index") };
      git(dir, ["read-tree", "HEAD"], { env });
      git(dir, ["add", "-A"], { env });
      const tree = gitOut(dir, ["write-tree"], { env });
      sha = gitOut(dir, ["commit-tree", tree, "-p", sha, "-m", `nexus backup of ${branch} before merge`], { env });
    } finally {
      fs.rmSync(scratch, { recursive: true, force: true });
    }
  }
  git(dir, ["update-ref", "-m", "nexus: backup before merge", `refs/nexus-backup/${branch}`, sha]);
  return sha;
}

export function mergeWorktree(ctx: WorktreeContext, options: MergeOptions = {}): CommandResult {
  const repo = openRepo(ctx.cwd);
  const source = currentEntry(repo);
  if (!source || source.isMain) throw new WorktreeError("run `worktree merge` from inside the worktree you want to merge, not the main checkout");
  if (!source.branch) throw new WorktreeError("the current worktree is on a detached HEAD; create a branch first");
  const branch = source.branch;
  const targetName = options.target ? resolveBranchName(repo, options.target) : defaultBranch(repo);
  if (!targetName) throw new WorktreeError("this repository has no default branch to merge into; pass a target");
  if (targetName === branch) throw new WorktreeError("the target is the branch being merged");
  const targetEntry = repo.entries.find((entry) => entry.branch === targetName);
  if (!targetEntry || targetEntry.prunable) throw new WorktreeError(`target ${shownBranch(targetName)} is not checked out in any worktree; run \`worktree switch ${shownBranch(targetName)}\` first`);

  // Receipt gate (the named-worktree equivalent of CAND-003): the exact state being merged needs a recorded passing
  // verification, or an explicit operator waiver with a reason. Checked before anything is changed.
  const gateState = workingState(source.path, statusOf(source.path).total > 0);
  const registry = readRegistry(repo.commonDir).registry;
  let waiver: string | undefined;
  if (!hasVerification(registry, branch, gateState)) {
    if (!options.noVerifyReceipt) {
      throw new WorktreeError(
        `no recorded passing verification for ${shownBranch(branch)} at ${gateState.head.slice(0, 12)}${gateState.dirty ? " plus uncommitted changes" : ""}. ` +
        "Run your verifier in this worktree through a Nexus session, or merge anyway with --no-verify-receipt --reason \"why\" (the reason is recorded).");
    }
    const reason = redactSecrets((options.reason ?? "").trim()).slice(0, 200);
    if (reason.length < 3) throw new WorktreeError("--no-verify-receipt needs --reason \"why\" (at least 3 characters); it is recorded");
    waiver = reason;
  }

  // preMerge: WP-1313 attaches the blocking pre-merge hook here, after the checks and before any history is rewritten.
  const gitDir = gitOut(source.path, ["rev-parse", "--path-format=absolute", "--git-dir"]);
  const busy = inProgress(gitDir);
  if (busy) throw new WorktreeError(`a ${busy.replace("-merge", "").replace("-apply", "")} is already in progress in this worktree; finish it (git rebase --continue / --abort) and run merge again`);
  const targetState = statusOf(targetEntry.path);
  if (targetState.total > 0) throw new WorktreeError(`the target worktree (${shownBranch(targetName)}) has uncommitted changes; commit or stash them first`);

  const notes: string[] = [];
  if (waiver !== undefined) {
    const reason = waiver;
    updateRegistry(repo.commonDir, (reg) => {
      reg.waivers = [...(reg.waivers ?? []), { branch, head: gateState.head, reason, recordedAt: new Date().toISOString() }].slice(-MAX_RECORDS);
    });
    notes.push(`Merging without a verification record (waiver recorded: ${reason}).`);
  }
  const state = statusOf(source.path);
  const targetSha = resolveCommit(repo, targetName);
  if (!targetSha) throw new WorktreeError(`target ${shownBranch(targetName)} does not name a commit`);
  const dirty = state.total > 0;
  const mergeBase = gitOut(source.path, ["merge-base", targetSha, "HEAD"], { allowFailure: false });
  const ahead = Number(gitOut(source.path, ["rev-list", "--count", `${mergeBase}..HEAD`]));
  if (!dirty && ahead === 0) {
    notes.push(`Nothing to merge: ${shownBranch(branch)} has no commits beyond ${shownBranch(targetName)}.`);
  } else {
    backup(source.path, branch, dirty);
    notes.push(`Backed up ${shownBranch(branch)} to refs/nexus-backup/${shownBranch(branch)}.`);
  }

  if (dirty) {
    const message = options.message ?? generateConventionalCommit(source.path).message;
    git(source.path, ["add", "-A"]);
    git(source.path, ["commit", "-m", message], { env: NON_INTERACTIVE });
    notes.push("Committed the uncommitted changes.");
  }

  const count = Number(gitOut(source.path, ["rev-list", "--count", `${mergeBase}..HEAD`]));
  if (count > 1 && !options.noSquash) {
    const subjects = gitOut(source.path, ["log", "--reverse", "--format=%s", `${mergeBase}..HEAD`]).split("\n").filter(Boolean);
    const message = options.message ?? `${subjects[0]}\n\nSquashed ${count} commits from ${branch}:\n${subjects.map((s) => `- ${s}`).join("\n")}`;
    git(source.path, ["reset", "--soft", mergeBase]);
    git(source.path, ["commit", "-m", message], { env: NON_INTERACTIVE });
    notes.push(`Squashed ${count} commits.`);
  }

  if (!options.noRebase && mergeBase !== targetSha) {
    const rebase = git(source.path, ["rebase", targetSha], { allowFailure: true, env: NON_INTERACTIVE });
    if (rebase.status !== 0) {
      const open = inProgress(gitOut(source.path, ["rev-parse", "--path-format=absolute", "--git-dir"]));
      if (!open) throw new WorktreeError(`rebase onto ${shownBranch(targetName)} failed: ${redactSecrets(rebase.stderr.trim().split("\n")[0] ?? "")}`);
      const files = git(source.path, ["diff", "--name-only", "--diff-filter=U"], { allowFailure: true }).stdout.split("\n").filter(Boolean).slice(0, 10);
      return {
        success: false,
        output: `Rebase onto ${shownBranch(targetName)} stopped on conflicts${files.length ? ` in ${files.map((f) => redactSecrets(f)).join(", ")}` : ""}.\n` +
          `The rebase is left open in ${shownPath(ctx.home, source.path)}: resolve the files, run \`git rebase --continue\` there and merge again, or \`git rebase --abort\` to undo it. ${targetName} was not changed.`,
      };
    }
    notes.push(`Rebased onto ${shownBranch(targetName)}.`);
  }

  const ff = git(targetEntry.path, ["merge", "--ff-only", "--no-edit", "--end-of-options", branch], { allowFailure: true, env: NON_INTERACTIVE });
  if (ff.status !== 0) {
    throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${options.noRebase ? "the branch is not a descendant of the target (merge without --no-rebase)" : "the target moved while merging; run merge again"}`);
  }
  notes.push(`Fast-forwarded ${shownBranch(targetName)}.`);

  if (!options.noRemove) {
    // The merged work is on the target. What is left in the worktree is ignored output (build caches), which goes with it.
    notes.push(removeOne({ ...ctx, cwd: targetEntry.path }, source.path, { force: true }));
  }
  return { success: true, output: notes.join("\n"), data: { branch, target: targetName } };
}

// ---- prune ----------------------------------------------------------------------------------------------------

export interface PruneOptions { dryRun?: boolean; minAgeMs?: number; limit?: number; discardIgnored?: boolean }

const DAY_MS = 86_400_000;
const REPORT_LINES = 40;

export function parseAge(text: string): number {
  const match = /^(\d+)([smhdw])$/.exec(text);
  if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
  const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
  return Number(match[1]) * unit;
}

export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
  const minAge = options.minAgeMs ?? DAY_MS;
  const limit = Math.max(1, options.limit ?? 100);
  const repo = openRepo(ctx.cwd);
  const here = currentEntry(repo);
  const registry = readRegistry(repo.commonDir).registry;
  const target = defaultBranch(repo);
  const targetSha = target ? resolveCommit(repo, target) : undefined;
  if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");

  const taskBase = path.join(repo.repoPath, ".nexus", "worktrees") + path.sep;
  const lines: string[] = [];
  const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
  let limited = false;
  const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
  const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
  const now = Date.now();

  for (const entry of repo.entries) {
    if (entry.isMain || entry === here) continue;
    if (counts.removed >= limit) { limited = true; break; }
    if (entry.prunable) { counts.stale++; continue; }
    if (entry.locked) { keep(entry, "locked"); continue; }
    if (entry.branch?.startsWith("nexus/") && entry.path.startsWith(taskBase)) { keep(entry, "speculative task worktree"); continue; }
    try {
      const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
      if (now - touched < minAge) { counts.young++; continue; }
      const reason = integratedReason(repo, entry.head, targetSha);
      if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
      const dirty = statusOf(entry.path, { ignored: true });
      if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
      if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
      if (options.dryRun) {
        counts.removed++;
        lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
        continue;
      }
      removeOne(ctx, entry.path, { force: dirty.ignored > 0 });
      counts.removed++;
      lines.push(`removed ${label(entry)} (integrated: ${reason})`);
    } catch (err) {
      keep(entry, redactSecrets((err as Error).message).slice(0, 160));
    }
  }

  if (counts.stale > 0 && !options.dryRun) git(repo.cwd, ["worktree", "prune"]);
  const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be" : ""} pruned` : ""}.`;
  const shown = lines.slice(0, REPORT_LINES);
  if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
  if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
  return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
}

